// ── TEMPORAL RESOLVER (TEMPORAL v1 · Step 6.2) ───────────────────────────
// CANONICAL. Snapshotted into each site by scripts/sync-cole-lib.mjs.
//
// THE ONLY PLACE A DATE IS COMPUTED. The email scheduler reads this and nothing
// else; lookupDeadline() against the hand-authored lib/product-deadlines.ts is
// retired by this file.
//
// Everything here is pure: (declaration, answers, now) → resolution. No I/O, no
// clock read of its own (`now` is always passed), so every branch is testable.
//
// DATES ARE CALENDAR DATES, NOT INSTANTS. A deadline like "30 June" is a day in
// a jurisdiction, not a moment in UTC. Resolving to YYYY-MM-DD in the declared
// timezone avoids an entire class of off-by-one-day bugs, and matches
// email_queue.trigger_date, which is a DATE column. The old code stored
// "2026-06-30T23:59:59.000+10:00" and then split on "T" anyway.

import type {
  TemporalDeclaration,
  ComputableRule,
  FixedRule,
  UserRule,
  TemporalResolution,
  WindowResolution,
  BusinessDayShift,
} from "./temporal-types";

// ── CALENDAR HELPERS ─────────────────────────────────────────────────────
// Deliberately no date library. Everything is calendar arithmetic on
// (year, month, day) triples, which needs no dependency and no offset table.

interface Ymd { y: number; m: number; d: number }   // m is 1-12

/** Today's CALENDAR date in an IANA zone. This is the only tz-aware operation. */
export function todayInZone(now: Date, timezone: string): Ymd {
  // en-CA formats as YYYY-MM-DD, which parses without locale ambiguity.
  // An invalid zone throws RangeError; callers treat that as unresolvable
  // rather than silently falling back to UTC and shifting the date a day.
  const iso = new Intl.DateTimeFormat("en-CA", {
    timeZone: timezone, year: "numeric", month: "2-digit", day: "2-digit",
  }).format(now);
  const [y, m, d] = iso.split("-").map(Number);
  return { y, m, d };
}

function daysInMonth(y: number, m: number): number {
  return new Date(Date.UTC(y, m, 0)).getUTCDate();   // m is 1-12; day 0 = last of m
}

function clampDay(y: number, m: number, d: number): number {
  return Math.min(d, daysInMonth(y, m));
}

function toIso({ y, m, d }: Ymd): string {
  return `${y}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
}

function parseIsoDate(s: string): Ymd | null {
  const match = /^(\d{4})-(\d{2})-(\d{2})/.exec(s.trim());
  if (!match) return null;
  const y = Number(match[1]), m = Number(match[2]), d = Number(match[3]);
  if (m < 1 || m > 12 || d < 1 || d > daysInMonth(y, m)) return null;
  return { y, m, d };
}

/** Compare two calendar dates. <0 if a before b. */
function cmp(a: Ymd, b: Ymd): number {
  return a.y !== b.y ? a.y - b.y : a.m !== b.m ? a.m - b.m : a.d - b.d;
}

function addDays(ymd: Ymd, n: number): Ymd {
  const dt = new Date(Date.UTC(ymd.y, ymd.m - 1, ymd.d));
  dt.setUTCDate(dt.getUTCDate() + n);
  return { y: dt.getUTCFullYear(), m: dt.getUTCMonth() + 1, d: dt.getUTCDate() };
}

function addMonths(ymd: Ymd, n: number): Ymd {
  const total = (ymd.y * 12) + (ymd.m - 1) + n;
  const y = Math.floor(total / 12);
  const m = (total % 12) + 1;
  return { y, m, d: clampDay(y, m, ymd.d) };
}

function dayOfWeek(ymd: Ymd): number {   // 0 = Sunday, 6 = Saturday
  return new Date(Date.UTC(ymd.y, ymd.m - 1, ymd.d)).getUTCDay();
}

// LIMITATION, STATED RATHER THAN HIDDEN: this shifts off WEEKENDS only. Public
// holidays are jurisdiction- and year-specific and this system holds no holiday
// calendar. A declaration whose date must dodge public holidays is not fully
// served by `shift` — declare it `unresolvable` rather than accept a date that
// is quietly wrong a few days a year.
function applyShift(ymd: Ymd, shift: BusinessDayShift): Ymd {
  if (shift === "none") return ymd;
  const step = shift === "next_business_day" ? 1 : -1;
  let out = ymd;
  for (let guard = 0; guard < 7; guard++) {
    const dow = dayOfWeek(out);
    if (dow !== 0 && dow !== 6) return out;
    out = addDays(out, step);
  }
  return out;   // unreachable: 7 steps always clears a weekend
}

// ── RULE → CALENDAR DATE ─────────────────────────────────────────────────

/**
 * Next occurrence of a fixed recurrence at or after `today`.
 * There is no stored date to go stale: "30 June" resolves to 2026-06-30 while
 * that is future, and to 2027-06-30 from 1 July 2026 onward — automatically.
 */
function resolveFixed(rule: FixedRule, today: Ymd): { date: Ymd } | { expired: Ymd } | { unresolvable: string } {
  if (rule.day < 1 || rule.day > 31) return { unresolvable: `invalid_day:${rule.day}` };

  if (rule.recurrence === "one_off") {
    // A true one-off must name its year, else "next occurrence" is meaningless.
    if (!rule.year || !rule.month) return { unresolvable: "one_off_requires_year_and_month" };
    const d = { y: rule.year, m: rule.month, d: clampDay(rule.year, rule.month, rule.day) };
    const shifted = applyShift(d, rule.shift);
    // A one-off does NOT roll forward — once gone it is gone, and saying so is
    // the whole point of the EXPIRED status.
    return cmp(shifted, today) < 0 ? { expired: shifted } : { date: shifted };
  }

  if (rule.recurrence === "annual") {
    if (!rule.month) return { unresolvable: "annual_requires_month" };
    for (const y of [today.y, today.y + 1]) {
      const d = applyShift({ y, m: rule.month, d: clampDay(y, rule.month, rule.day) }, rule.shift);
      if (cmp(d, today) >= 0) return { date: d };
    }
    return { unresolvable: "annual_no_future_occurrence" };
  }

  if (rule.recurrence === "monthly") {
    for (let i = 0; i < 2; i++) {
      const base = addMonths({ y: today.y, m: today.m, d: 1 }, i);
      const d = applyShift({ ...base, d: clampDay(base.y, base.m, rule.day) }, rule.shift);
      if (cmp(d, today) >= 0) return { date: d };
    }
    return { unresolvable: "monthly_no_future_occurrence" };
  }

  // quarterly — every 3 months from the anchor month, whichever comes next.
  if (rule.recurrence === "quarterly") {
    const anchor = rule.month ?? 1;
    for (let i = 0; i < 5; i++) {
      // Walk the anchor forward in 3-month steps across this year and the next.
      const stepped = addMonths({ y: today.y, m: anchor, d: 1 }, i * 3);
      const d = applyShift({ ...stepped, d: clampDay(stepped.y, stepped.m, rule.day) }, rule.shift);
      if (cmp(d, today) >= 0) return { date: d };
    }
    return { unresolvable: "quarterly_no_future_occurrence" };
  }

  return { unresolvable: `unknown_recurrence:${String((rule as FixedRule).recurrence)}` };
}

/**
 * A date the CUSTOMER gave us, plus an optional offset.
 * Absent, blank or unparseable → UNRESOLVABLE. Never a guess, never a default:
 * a manufactured customer deadline is the error this whole step exists to stop.
 */
function resolveUser(
  rule: UserRule,
  answers: Record<string, unknown> | null,
  today: Ymd,
): { date: Ymd } | { expired: Ymd } | { unresolvable: string } {
  if (!answers) return { unresolvable: `no_answers_supplied:${rule.field}` };

  const raw = answers[rule.field];
  if (raw === undefined || raw === null || raw === "") {
    return { unresolvable: `answer_missing:${rule.field}` };
  }
  if (typeof raw !== "string" && !(raw instanceof Date)) {
    return { unresolvable: `answer_not_a_date:${rule.field}` };
  }

  const base = raw instanceof Date
    ? { y: raw.getUTCFullYear(), m: raw.getUTCMonth() + 1, d: raw.getUTCDate() }
    : parseIsoDate(raw);
  if (!base) return { unresolvable: `answer_unparseable:${rule.field}` };

  let out = base;
  if (rule.offset?.months) out = addMonths(out, rule.offset.months);
  if (rule.offset?.days)   out = addDays(out, rule.offset.days);
  out = applyShift(out, rule.shift);

  return cmp(out, today) < 0 ? { expired: out } : { date: out };
}

function resolveRule(
  rule: ComputableRule,
  answers: Record<string, unknown> | null,
  now: Date,
  label: string | undefined,
): TemporalResolution {
  let today: Ymd;
  try {
    today = todayInZone(now, rule.timezone);
  } catch {
    return { status: "UNRESOLVABLE", reason: `invalid_timezone:${rule.timezone}` };
  }

  const outcome = rule.source === "fixed"
    ? resolveFixed(rule, today)
    : resolveUser(rule, answers, today);

  if ("unresolvable" in outcome) return { status: "UNRESOLVABLE", reason: outcome.unresolvable };
  if ("expired" in outcome)      return { status: "EXPIRED", date: toIso(outcome.expired), timezone: rule.timezone };
  return { status: "RESOLVED", date: toIso(outcome.date), label, timezone: rule.timezone };
}

// ── THE ENTRY POINT ──────────────────────────────────────────────────────

/**
 * resolve(declaration, answers, now) → NONE | RESOLVED | UNRESOLVABLE | EXPIRED
 *                                      (+ UNDECLARED)
 *
 * UNDECLARED is a distinct status, not a flavour of NONE. Both are silent, but
 * only NONE is evidence that somebody decided. Collapsing them would make the
 * gate unable to tell "declared: no date" from "nobody said", which is exactly
 * the distinction 6.4 exists to enforce. (Same principle as Step 4.8b's
 * never_ran vs stale.)
 */
export function resolve(
  declaration: TemporalDeclaration | null | undefined,
  answers: Record<string, unknown> | null,
  now: Date,
): TemporalResolution {
  if (!declaration) return { status: "UNDECLARED" };

  switch (declaration.kind) {
    case "none":
      return { status: "NONE", reason: declaration.reason };

    case "unresolvable":
      return { status: "UNRESOLVABLE", reason: declaration.reason, detail: declaration.detail };

    case "deadline":
    case "effective_from":
      return resolveRule(declaration.rule, answers, now, declaration.label);

    case "window": {
      // A window's single-value resolution is its CLOSES edge: that is the
      // act-by date a reminder would ever be anchored to. resolveWindow() below
      // exposes both edges for a caller that needs them.
      return resolveRule(declaration.closes, answers, now, declaration.label);
    }

    default: {
      // Exhaustiveness guard. An unrecognised kind is loudly unresolvable, never
      // silently treated as "no date" — an unknown declaration is not a decision.
      const unknown = declaration as { kind?: string };
      return { status: "UNRESOLVABLE", reason: `unknown_kind:${String(unknown.kind)}` };
    }
  }
}

/** Both edges of a window declaration. Non-window kinds resolve both to the same value. */
export function resolveWindow(
  declaration: TemporalDeclaration | null | undefined,
  answers: Record<string, unknown> | null,
  now: Date,
): WindowResolution {
  if (declaration && declaration.kind === "window") {
    return {
      opens:  resolveRule(declaration.opens,  answers, now, declaration.label),
      closes: resolveRule(declaration.closes, answers, now, declaration.label),
    };
  }
  const single = resolve(declaration, answers, now);
  return { opens: single, closes: single };
}

/**
 * The scheduler's question, in one call: may this product be emailed a date?
 * ONLY a RESOLVED future date qualifies. UNDECLARED, NONE, UNRESOLVABLE and
 * EXPIRED are all silence — 6.3's "no fallback to any other date, ever",
 * expressed as code rather than as a convention callers must remember.
 */
export function schedulableDate(res: TemporalResolution): { date: string; timezone: string; label?: string } | null {
  return res.status === "RESOLVED"
    ? { date: res.date, timezone: res.timezone, label: res.label }
    : null;
}
